INSERT INTO meal_log_items (
    meal_log_id, item_type, food_code, item_name, quantity, quantity_unit, recipe_payload
) VALUES (
    #{mealLogId}, 'CONSUMED', #{foodCode}, #{name}, #{quantity}, #{unit}, NULL
)

mapper.select:
SELECT meal_log_id AS id, user_id AS userId, meal_type AS mealType, eaten_at AS eatenAt, memo, created_at AS createdAt FROM meal_logs WHERE user_id = #{userId} AND log_type = 'CONSUMED'
AND DATE(eaten_at) = #{date}
ORDER BY eaten_at DESC, meal_log_id DESC

mapper.delete:
DELETE i
FROM meal_log_items i
JOIN meal_logs l ON l.meal_log_id = i.meal_log_id
WHERE i.meal_log_id = #{mealLogId}
  AND l.user_id = #{userId}
  AND l.log_type = 'CONSUMED'

DELETE FROM meal_logs
WHERE meal_log_id = #{mealLogId}
  AND user_id = #{userId}
  AND log_type = 'CONSUMED'

